package com.learningspace;
import android.app.*;import android.app.job.*;import android.content.*;import android.os.*;import org.json.*;import java.io.*;import java.net.*;import java.nio.file.*;import java.time.*;import java.util.concurrent.atomic.AtomicBoolean;
/** One persisted, network-constrained job. Android may defer it; opening the app catches up. */
public class DailyCoachJob extends JobService {
 private static final int JOB=7205,NOTICE=7206;private static final AtomicBoolean RUNNING=new AtomicBoolean();private final AtomicBoolean stopped=new AtomicBoolean();
 private static File templateFile(Context c){return new File(c.getFilesDir(),"daily-coach-template.json");}
 private static File receiptFile(Context c){return new File(c.getFilesDir(),"daily-coach-receipt.json");}
 private static JSONObject read(File f)throws Exception{return f.exists()?new JSONObject(new String(Files.readAllBytes(f.toPath()),"UTF-8")):new JSONObject();}
 private static synchronized void write(File f,JSONObject value)throws Exception{File tmp=new File(f.getPath()+".tmp");try(FileOutputStream out=new FileOutputStream(tmp)){out.write(value.toString().getBytes("UTF-8"));out.getFD().sync();}Files.move(tmp.toPath(),f.toPath(),StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}
 public static synchronized String configure(Context c,String raw)throws Exception{
  if(raw==null||raw.length()>500000)throw new Exception("Daily context is too large");JSONObject data=new JSONObject(raw);ZoneId.of(data.getString("timezone"));if(!data.has("body")||data.getInt("revision")<0)throw new Exception("Invalid daily context");write(templateFile(c),data);schedule(c);return status(c);
 }
 public static synchronized void schedule(Context c){if(RUNNING.get())return;try{JSONObject data=read(templateFile(c));JobScheduler jobs=c.getSystemService(JobScheduler.class);if(!data.optBoolean("enabled")||new PhoneKeyStore(c).key().isEmpty()){jobs.cancel(JOB);return;}Instant now=Instant.now();String zone=data.getString("timezone"),day=DailyCoachContext.day(now,zone),id=day+"@"+zone;boolean exists=false;JSONObject packet=read(new File(c.getFilesDir(),"library.json"));JSONArray reviews=packet.getJSONObject("state").getJSONObject("coach").optJSONArray("dailyReviews");if(reviews!=null)for(int i=0;i<reviews.length();i++)if(id.equals(reviews.getJSONObject(i).optString("id")))exists=true;android.content.SharedPreferences p=c.getSharedPreferences("daily_coach",0);int attempts=day.equals(p.getString("day",""))?p.getInt("attempts",0):0;long when=DailyCoachContext.nextMidnight(now,zone);if(!exists&&attempts<3){long retry=day.equals(p.getString("day",""))?p.getLong("retryAt",0):0;when=retry>0?Math.max(now.toEpochMilli()+1000,retry):now.toEpochMilli()+90000;}int result=jobs.schedule(new JobInfo.Builder(JOB,new ComponentName(c,DailyCoachJob.class)).setMinimumLatency(Math.max(1000,when-now.toEpochMilli())).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setPersisted(true).setBackoffCriteria(30*60*1000,JobInfo.BACKOFF_POLICY_EXPONENTIAL).build());p.edit().putLong("scheduledFor",result==JobScheduler.RESULT_SUCCESS?when:0).commit();}catch(Exception ignored){}}
 public static String status(Context c)throws Exception{JSONObject t=read(templateFile(c));android.content.SharedPreferences p=c.getSharedPreferences("daily_coach",0);boolean enabled=t.optBoolean("enabled"),key=!new PhoneKeyStore(c).key().isEmpty();return new JSONObject().put("supported",true).put("enabled",enabled).put("connected",key).put("running",RUNNING.get()).put("lastDay",p.getString("day","")).put("attempts",p.getInt("attempts",0)).put("error",p.getString("error","")).put("preparedAt",t.optString("preparedAt")).put("nextAt",enabled&&key&&p.getLong("scheduledFor",0)>0?Instant.ofEpochMilli(p.getLong("scheduledFor",0)).toString():"").put("notificationsEnabled",StudyTimerService.notificationsEnabled(c)).toString();}
 @Override public boolean onStartJob(JobParameters params){stopped.set(false);new Thread(()->{boolean retry=false;try{perform(this,"",false,false,stopped,Build.VERSION.SDK_INT>=28?params.getNetwork():null);}catch(Exception e){retry=!stopped.get();}finally{if(!stopped.get()){jobFinished(params,retry);if(!retry)new Handler(Looper.getMainLooper()).post(()->schedule(this));}}},"LearningDailyCoach").start();return true;}
 @Override public boolean onStopJob(JobParameters params){stopped.set(true);return true;}
 public static JSONObject perform(Context c,String requestedDay,boolean manual,boolean force,AtomicBoolean cancelled,android.net.Network network)throws Exception{
  if(!RUNNING.compareAndSet(false,true))throw new Exception("A daily review is already running. Check again shortly.");
  android.content.SharedPreferences prefs=c.getSharedPreferences("daily_coach",0);
  try{
   JSONObject template=read(templateFile(c));String zone=template.getString("timezone"),day=DailyCoachContext.day(Instant.now(),zone),id=day+"@"+zone;
   if(!requestedDay.isEmpty()&&!requestedDay.equals(day))throw new Exception("This phone reviews the latest completed day.");
   LocalLibrary library=new LocalLibrary(new File(c.getFilesDir(),"library.json"));JSONObject packet=new JSONObject(library.read()),state=packet.getJSONObject("state"),coach=state.getJSONObject("coach");
   if(!manual&&!coach.optBoolean("dailyEnabled",true))return new JSONObject().put("paused",true);
   JSONArray reviews=coach.optJSONArray("dailyReviews");if(!force&&reviews!=null)for(int i=0;i<reviews.length();i++)if(id.equals(reviews.getJSONObject(i).optString("id")))return new JSONObject().put("review",reviews.getJSONObject(i));
   JSONObject receipt=read(receiptFile(c)),review=null;if(id.equals(receipt.optString("id"))&&receipt.optString("activitySignature").equals(template.getJSONObject("signatures").optString(day,template.getString("emptySignature"))))review=receipt;
   if(review==null){
    if(template.getInt("revision")!=packet.getInt("revision"))throw new Exception("Open Learning Space to refresh the saved daily context before this review.");
    int attempts=day.equals(prefs.getString("day",""))?prefs.getInt("attempts",0):0;if(!manual&&attempts>=3)return new JSONObject().put("paused",true);
    prefs.edit().putString("day",day).putInt("attempts",attempts+1).putString("error","").commit();
    JSONObject body=DailyCoachContext.request(template,day,Instant.now()),input=new JSONObject(body.getString("input")),context=input.getJSONObject("context");
    addUsage(c,context,state,zone);addShares(c,context);body.put("input",input.toString());
    PhoneKeyStore keys=new PhoneKeyStore(c);String key=keys.key();if(key.isEmpty())throw new Exception("Add your OpenAI key in Settings.");body.put("model",keys.model()).put("store",false);
    JSONObject reply=DailyCoachContext.parseReply(call(body,key,network));String signature=template.getJSONObject("signatures").optString(day,template.getString("emptySignature"));
    review=new JSONObject().put("id",id).put("day",day).put("timezone",zone).put("at",Instant.now().toString()).put("source","phone").put("activitySignature",signature).put("snapshotAt",template.getString("preparedAt")).put("reply",reply);
    write(receiptFile(c),review); // Save the paid result before attempting a library write.
   }
   if(cancelled.get())throw new Exception("Review paused by Android. It will be recovered on retry.");
   boolean saved=false;
   for(int attempt=0;attempt<4&&!saved;attempt++){
    JSONObject latest=new JSONObject(library.read()),current=latest.getJSONObject("state"),currentCoach=current.getJSONObject("coach");if(!manual&&!currentCoach.optBoolean("dailyEnabled",true))return new JSONObject().put("paused",true);
    JSONArray old=currentCoach.optJSONArray("dailyReviews"),merged=new JSONArray().put(review);if(old!=null)for(int i=0;i<old.length()&&merged.length()<60;i++){JSONObject r=old.getJSONObject(i);if(!id.equals(r.optString("id")))merged.put(r);}currentCoach.put("dailyReviews",merged);
    JSONObject result=new JSONObject(library.save(latest.toString()));saved=!result.has("error");if(saved&&latest.getInt("revision")==packet.getInt("revision")){template.put("revision",result.getInt("revision"));JSONObject savedBody=template.getJSONObject("body"),savedInput=new JSONObject(savedBody.getString("input"));savedInput.getJSONObject("context").getJSONObject("automatic").put("continuity",new JSONObject().put("reviewDay",day).put("at",review.getString("at")).put("checkpoint",review.getJSONObject("reply").getString("checkpoint")));savedBody.put("input",savedInput.toString());write(templateFile(c),template);}
   }
   if(!saved)throw new Exception("Review is safe on this phone. Reopen the app to finish saving it.");
   prefs.edit().putString("error","").putLong("retryAt",0).commit();notifyReady(c,review);return new JSONObject().put("review",review);
  }catch(Exception e){prefs.edit().putLong("retryAt",System.currentTimeMillis()+30*60*1000L).putString("error",e.getMessage()==null?"Daily review could not finish. Open the app to retry.":e.getMessage()).commit();throw e;}finally{RUNNING.set(false);if(manual)schedule(c);}
 }
 private static JSONObject call(JSONObject body,String key,android.net.Network network)throws Exception{
  HttpURLConnection connection=(HttpURLConnection)(network==null?new URL("https://api.openai.com/v1/responses").openConnection():network.openConnection(new URL("https://api.openai.com/v1/responses")));connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(8000);connection.setReadTimeout(45000);connection.setRequestMethod("POST");connection.setRequestProperty("Authorization","Bearer "+key);connection.setRequestProperty("Content-Type","application/json");connection.setDoOutput(true);
  try{try(OutputStream out=connection.getOutputStream()){out.write(body.toString().getBytes("UTF-8"));}if(connection.getResponseCode()!=200)throw new Exception("OpenAI could not generate the daily review. Check your key, model, quota, or connection.");try(InputStream in=connection.getInputStream();ByteArrayOutputStream bytes=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){bytes.write(buffer,0,n);if(bytes.size()>500000)throw new Exception("AI response too large");}return new JSONObject(bytes.toString("UTF-8"));}}finally{connection.disconnect();}
 }
 private static void addShares(Context c,JSONObject context)throws Exception{
  JSONArray pending=ShareDrafts.read(new File(c.getFilesDir(),"pending-shares.json"));JSONArray safe=new JSONArray();for(int i=0;i<pending.length();i++){JSONObject item=pending.getJSONObject(i);String text=item.getString("text");safe.put(new JSONObject().put("id",item.getString("id")).put("createdAt",item.getString("createdAt")).put("text",text.substring(0,Math.min(1500,text.length()))).put("truncated",text.length()>1500));}context.put("pendingPhoneShares",safe); // Saved links/text only; no page fetch.
 }
 private static void addUsage(Context c,JSONObject context,JSONObject state,String zone)throws Exception{
  if(!state.getJSONObject("coach").optBoolean("useScreenTime",true))return;
  JSONArray summary=new JSONArray();String raw=c.getSharedPreferences("local_preferences",0).getString("focus-balance","");JSONObject settings=raw.isEmpty()?new JSONObject():new JSONObject(raw);if(settings.optBoolean("enabled")&&FocusUsage.granted(c)){try{JSONObject usage=new JSONObject(FocusUsage.report(c,zone)),categories=settings.optJSONObject("categories");JSONArray days=usage.getJSONArray("days"),localUnused=new JSONArray();boolean leisureConfigured=false;if(categories!=null){java.util.Iterator<String> it=categories.keys();while(it.hasNext())if("leisure".equals(categories.optString(it.next())))leisureConfigured=true;}
  for(int i=0;i<days.length();i++){JSONObject d=days.getJSONObject(i);JSONArray apps=d.getJSONArray("apps");if(apps.length()==0)continue;double leisure=0,learning=0,mixed=0,neutral=0;JSONArray names=new JSONArray();for(int a=0;a<apps.length();a++){JSONObject app=apps.getJSONObject(a);double minutes=app.getDouble("minutes");String category=categories==null?"neutral":categories.optString(app.getString("id"),"neutral");if(category.equals("leisure")){leisure+=minutes;if(settings.optBoolean("shareAppNames")&&names.length()<5)names.put(new JSONObject().put("name",app.getString("name")).put("minutes",minutes));}else if(category.equals("learning"))learning+=minutes;else if(category.equals("mixed"))mixed+=minutes;else neutral+=minutes;}summary.put(new JSONObject().put("device","Phone").put("platform","android").put("day",d.getString("day")).put("capturedAt",usage.getString("capturedAt")).put("totalMinutes",leisure+learning+mixed+neutral).put("leisureMinutes",leisureConfigured?leisure:JSONObject.NULL).put("learningAppMinutes",learning).put("mixedMinutes",mixed).put("unclassifiedMinutes",neutral).put("budgetMinutes",settings.optInt("budgetMinutes",60)).put("partial",true).put("topLeisureApps",names));}
  }catch(Exception unavailable){context.put("phoneUsageUnavailable",true);}}
  // Preserve approved remote Mac estimates from the latest library, with their own freshness.
  JSONArray shared=state.optJSONArray("screenTime");String today=LocalDate.now(ZoneId.of(zone)).toString(),start=LocalDate.parse(today).minusDays(6).toString();if(shared!=null)for(int i=0;i<shared.length();i++){JSONObject row=shared.getJSONObject(i);if("mac".equals(row.optString("platform"))&&row.optString("day").compareTo(start)>=0&&row.optString("day").compareTo(today)<=0&&ZoneId.of(row.getString("timezone")).getRules().equals(ZoneId.of(zone).getRules())&&summary.length()<28){JSONObject r=new JSONObject(row.toString());r.remove("id");r.remove("deviceId");r.put("device",r.optString("deviceName","Mac")).put("leisureMinutes",r.optBoolean("leisureConfigured")?r.optDouble("leisureMinutes"):JSONObject.NULL);summary.put(r);}}
  context.put("screenTime",new JSONObject().put("scope","Available foreground estimates. User-assigned labels. Missing usage is unknown. Devices overlap; totals are not elapsed free time. Phone readings refreshed when access is available; remote estimates retain their capture dates.").put("days",summary));
 }
 private static void notifyReady(Context c,JSONObject review)throws Exception{
  android.content.SharedPreferences p=c.getSharedPreferences("daily_coach",0);String id=review.getString("id");if(id.equals(p.getString("notified","")))return;NotificationManager manager=c.getSystemService(NotificationManager.class);manager.createNotificationChannel(new NotificationChannel("daily_coach","Daily coach reviews",NotificationManager.IMPORTANCE_DEFAULT));
  if(StudyTimerService.notificationsEnabled(c)){Intent open=new Intent(c,MainActivity.class).putExtra("path","?page=coach").addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent action=PendingIntent.getActivity(c,NOTICE,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification publicView=new Notification.Builder(c,"daily_coach").setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("Your daily coach review is ready").build();Notification n=new Notification.Builder(c,"daily_coach").setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("Your daily coach review is ready").setContentText(review.getJSONObject("reply").getString("headline")).setContentIntent(action).setAutoCancel(true).setVisibility(Notification.VISIBILITY_PRIVATE).setPublicVersion(publicView).build();manager.notify(NOTICE,n);p.edit().putString("notified",id).commit();}
 }
}
